//! The public contract of `query::validate` over query text, as the validate oracle records it (build/ports/stage2/validate-oracle):
//! each row is the smallest query that gives one typed refusal (its variant, its span, its message), and the accepted rows the change
//! of the one lowering decided. A row names its query by the file it is read from (a rule of a pack, or a fixture) and the mutation
//! of one token the oracle made of it; the pack's module catalog is the one its `benchmark.toml` declares. The rows are generated by
//! `gen_contract_test.py` of that directory: a row that fails after a pack or fixture was edited is regenerated, not patched.

use ryo::linter::Languages;
use ryo::query::{QueryModuleCatalog, QueryModuleSource, RyoQlQuery, ValidateRequest, validate};
use std::path::{Path, PathBuf};

/// The token spans of a text: quoted strings, and runs of letters, digits, `_` and `-`.
fn tokens(text: &str) -> Vec<(usize, usize)> {
    let b = text.as_bytes();
    let (mut out, mut i) = (Vec::new(), 0);
    while i < b.len() {
        if b[i] == b'"' {
            let s = i;
            i += 1;
            while i < b.len() && b[i] != b'"' {
                if b[i] == b'\\' {
                    i += 1;
                }
                i += 1;
            }
            i = (i + 1).min(b.len());
            out.push((s, i));
        } else if b[i].is_ascii_alphanumeric() || b[i] == b'_' || b[i] == b'-' {
            let s = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_' || b[i] == b'-') {
                i += 1;
            }
            out.push((s, i));
        } else {
            i += 1;
        }
    }
    out
}

/// `text` with the mutation the oracle id names: `replaceN`, `deleteN` or `swapN` of its token N, or none for `base`.
fn mutated(text: &str, name: &str) -> String {
    if name == "base" {
        return text.to_owned();
    }
    let toks = tokens(text);
    let at: usize = name.trim_start_matches(|c: char| c.is_ascii_alphabetic()).parse().expect("a token number");
    let (s, e) = toks[at];
    let other = toks[(at + 1 + toks.len() / 2) % toks.len()];
    let middle = if name.starts_with("replace") {
        "zzz"
    } else if name.starts_with("swap") {
        &text[other.0..other.1]
    } else {
        ""
    };
    format!("{}{}{}", &text[..s], middle, &text[e..])
}

/// The module catalog of the nearest `benchmark.toml` above `query`, when it declares `[query-modules]`.
fn catalog_for(query: &Path) -> Option<QueryModuleCatalog> {
    let mut dir = query.parent();
    while let Some(d) = dir {
        let toml = d.join("benchmark.toml");
        if toml.is_file() {
            let text = std::fs::read_to_string(&toml).ok()?;
            let section = text.split("[query-modules]").nth(1)?;
            let mut sources = Vec::new();
            for line in section.lines().skip(1) {
                if line.starts_with('[') {
                    break;
                }
                let Some((name, path)) = line.split_once(" = ") else { continue };
                let (name, path) = (name.trim().trim_matches('"'), path.trim().trim_matches('"'));
                sources.push(QueryModuleSource::try_new(name, &std::fs::read_to_string(d.join(path)).ok()?).ok()?);
            }
            return QueryModuleCatalog::try_new(sources).ok();
        }
        dir = d.parent();
    }
    None
}

/// What `validate` answers for the query an oracle id names, with no language linked, as the text of its answer.
fn answered(id: &str) -> String {
    answered_in(id, &Languages(Vec::new()))
}

/// The same with the languages `languages` linked.
fn answered_in(id: &str, languages: &Languages) -> String {
    let root: PathBuf = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../..");
    let (path, name) = id.split_once('#').expect("an oracle id");
    let file = root.join(path);
    let text = mutated(&std::fs::read_to_string(&file).expect("the query file"), name);
    let query = match catalog_for(&file) {
        Some(catalog) => RyoQlQuery::with_modules(&format!("test/{}", file.parent().and_then(|p| p.file_name()).and_then(|n| n.to_str()).unwrap_or("")), &text, &catalog).map_err(|e| format!("{e:?}")),
        None => RyoQlQuery::try_from(text.as_str()).map_err(|e| format!("{e:?}")),
    };
    match query {
        Err(error) => format!("QUERY-ERR {error}"),
        Ok(query) => match validate(languages, ValidateRequest { query, hosted: Vec::new(), observations: Vec::new() }) {
            Ok(report) => format!("OK {report:?}"),
            Err(error) => format!("ERR {error:?}"),
        },
    }
}

